for (const [code, [topic, text, main, support, challenge, tail, wrongMain, off]] of Object.entries(INTERPS)) {
  const P = { passage: text, passageSource: 'An interpretation written for this app' };
  const w = items.find((i) => i.id === `history.m.${code}.w`);
  Object.assign(w, P, {
    prompt: `Read the interpretation, then answer: ${w.prompt} Use the interpretation and your own knowledge.`,
    hints: ['Say whether you agree with the interpretation, and why', ...w.hints],
    model: w.model + tail,
  });
  items.push(
    mcq(`m.${code}.i1`, topic, 'What is the main argument of this interpretation?', [[main, true], [wrongMain[0], false, 'Read it again: that is not the claim it makes.'], [wrongMain[1], false, 'Read it again: look for the sentence that sums up its view.']], `Its main claim: ${main}. Look for the sentence that sums up its view.`, P),
    mcq(`m.${code}.i2`, topic, 'Which piece of evidence best SUPPORTS this interpretation?', [[support, true], [challenge, false, 'This evidence actually challenges the interpretation.'], [off, false, 'True, but it is not evidence about this claim.']], 'Good historians test an interpretation against evidence, starting with what supports it.', P),
    mcq(`m.${code}.i3`, topic, 'Which piece of evidence best CHALLENGES this interpretation?', [[challenge, true], [support, false, 'This evidence supports the interpretation.'], [off, false, 'True, but it is not evidence about this claim.']], 'An interpretation is only convincing if it survives the evidence against it.', P),
  );
}

