for (const code of Object.keys(INTERPS)) {
  memory[`m.${code}.i1`] = { hook: 'Find the **claim**: the sentence that tells you what the writer wants you to believe, often the first one.' };
  memory[`m.${code}.i2`] = { hook: '**Support** = evidence that agrees with the claim. Ask: would the writer be glad to quote this?' };
  memory[`m.${code}.i3`] = { hook: '**Challenge** = evidence that pushes back. Look for something true that the writer has left out.' };
}

